export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }
  const result = [];
  for (const interval of intervals) {
    if (!Array.isArray(interval) || interval.length !== 2 || typeof interval[0] !== 'number' || typeof interval[1] !== 'number' || interval[0] > interval[1]) {
      throw new TypeError('each interval must be an array of two finite numbers');
    }
    if (result.length === 0 || result[result.length - 1][1] < interval[0]) {
      result.push(interval);
    } else {
      const last = result[result.length - 1];
      last[1] = Math.max(last[1], interval[1]);
    }
  }
  return result;
}
