export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const tokens = text.trim().split(/\s+/);
  const operatorPrecedence = {
    '^': 2,
    '*': 1,
    '/': 1,
    '+': 0,
    '-': 0
  };

  const operatorStack = [];
  const outputQueue = [];

  for (const token of tokens) {
    if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else if (token in operatorPrecedence) {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && operatorPrecedence[operatorStack[operatorStack.length - 1]] >= operatorPrecedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    } else if (!isNaN(parseFloat(token))) {
      outputQueue.push(parseFloat(token));
    } else {
      throw new SyntaxError(`Invalid token: ${token}`);
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];

  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      switch (token) {
        case '^':
          stack.push(Math.pow(a, b));
          break;
        case '*':
          stack.push(a * b);
          break;
        case '/':
          if (b === 0) {
            throw new RangeError('Division by zero');
          }
          stack.push(a / b);
          break;
        case '+':
          stack.push(a + b);
          break;
        case '-':
          stack.push(a - b);
          break;
      }
    }
  }

  if (stack.length !== 1) {
    throw new SyntaxError('Invalid expression');
  }

  return stack[0];
}
