export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('base and userPath must be strings');
  }

  const baseDir = new URL(base).pathname;
  if (baseDir === '') {
    throw new Error('base must be an absolute path');
  }

  const userPathParts = userPath.split(/\/|\\/);
  const stack = [];

  for (const part of userPathParts) {
    if (part === '..') {
      if (stack.length === 0 || stack[0] === '..') {
        throw new Error('attempt to climb above base');
      }
      stack.pop();
    } else if (part === '') {
      // ignore empty parts
    } else if (part === '.') {
      continue;
    } else if (part.includes('%') || part.includes('\x00')) {
      throw new Error('invalid percent-encoded or NUL byte');
    } else {
      stack.push(part);
    }
  }

  const result = stack.join('/');
  if (result.startsWith(baseDir)) {
    return result;
  } else {
    throw new Error('attempt to leave base');
  }
}
