export function parseCsv(text) {
  const rows = [];
  const lines = text.split(/\r?\n/);
  let currentRow = [];
  let inQuote = false;
  let currentField = '';

  for (const line of lines) {
    let i = 0;
    while (i < line.length) {
      const char = line[i];
      if (char === '"') {
        if (!inQuote) {
          inQuote = true;
        } else {
          inQuote = false;
          if (currentField && currentField[currentField.length - 1] === '"') {
            currentField = currentField.slice(0, -1);
          }
        }
      } else if (char === ',' && !inQuote) {
        currentRow.push(currentField);
        currentField = '';
      } else if (char === '\r' && i + 1 < line.length && line[i + 1] === '\n') {
        currentRow.push(currentField);
        currentField = '';
        break;
      } else {
        currentField += char;
      }
      i++;
    }
    if (inQuote) {
      throw new Error('Unclosed quote');
    }
    if (currentField) {
      currentRow.push(currentField);
    }
    if (currentRow.length > 0 || line.trim() !== '') {
      rows.push(currentRow);
      currentRow = [];
    }
  }
  if (currentRow.length > 0) {
    rows.push(currentRow);
