export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('Both base and userPath must be strings');
  }

  const baseParts = base.split(/\/|\\/);
  const userParts = userPath.split(/\/|\\/);

  for (const part of userParts) {
    if (part === '' || part === '.') {
      continue;
    }
    if (part === '..') {
      if (baseParts.length === 1) {
        throw new Error('Cannot climb above root');
      }
      baseParts.pop();
    } else if (part === '%2e' || part === '%2f' || part === '%5c' || part === '\x00') {
      throw new Error('Invalid character in userPath');
    } else if (part.startsWith('%')) {
      throw new Error('Percent-encoded characters are not allowed');
    } else if (part.startsWith('/')) {
      throw new Error('Absolute path in userPath');
    } else {
      baseParts.push(part);
    }
  }

  return baseParts.join('/');
}
