export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const tokens = text.match(/\s*([+-]?\d+(?:\.\d+)?|\^|\(|\)|\s+)/g);
  if (!tokens) {
    throw new SyntaxError('Invalid input');
  }

  const precedence = {
    '^': 2,
    '*': 1,
    '/': 1,
    '+': 0,
    '-': 0,
  };

  const outputQueue = [];
  const operatorStack = [];

  for (const token of tokens) {
    if (token === ' ') continue;
    if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop(); // Remove the '('
    } else if (precedence[token] !== undefined) {
      while (operatorStack.length > 0 && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    } else if (!isNaN(parseFloat(token))) {
      outputQueue.push(parseFloat(token));
    } else {
      throw new SyntaxError('Invalid character');
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];
  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const right = stack.pop();
      const left = stack.pop();
      switch (token) {
        case '^':
          stack.push(Math.pow(left, right));
          break;
        case '*':
          stack.push(left * right);
          break;
        case '/':
          if (right === 0) {
            throw new RangeError('Division by zero');
          }
          stack.push(left / right);
          break;
        case '+':
          stack.push(left + right);
          break;
        case '-':
          stack.push(left - right);
          break;
      }
    }
  }

  if (stack.length !== 1) {
    throw new SyntaxError('Unbalanced expression');
  }

  return stack[0];
}
