export function parseCsv(text) {
  const rows = text.trim().split(/\r?\n/);
  const result = [];
  let currentRow = [];
  let inQuote = false;
  let currentField = '';

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const trimmedRow = row.trim();

    if (trimmedRow === '') {
      if (currentRow.length > 0) {
        result.push(currentRow);
        currentRow = [];
      }
      continue;
    }

    if (trimmedRow.startsWith('"')) {
      inQuote = !inQuote;
      currentField += trimmedRow.slice(1);
    } else {
      if (inQuote) {
        currentField += trimmedRow;
      } else {
        const fields = trimmedRow.split(',');
        if (fields.length > 1) {
          currentRow.push(...fields);
        } else {
          currentField += trimmedRow;
        }
      }
    }

    if (inQuote) {
      currentField += '"';
    }

    if (trimmedRow.endsWith('"')) {
      inQuote = false;
      currentRow.push(currentField);
      currentField = '';
    }
  }

  if (currentRow.length > 0) {
    result.push(currentRow);
  }

  return result;
}
