export function safeJoinPath(base, userPath) {
    if (typeof base !== 'string' || typeof userPath !== 'string') {
        throw new TypeError('base and userPath must be strings');
    }

    if (!base.startsWith('/')) {
        throw new Error('base must be an absolute path');
    }

    const baseDir = base.replace(/\/$/, '');
    const path = require('path');

    const normalizedPath = path.normalize(base + '/' + userPath);

    if (normalizedPath.startsWith(baseDir)) {
        return normalizedPath;
    }

    if (normalizedPath.includes('%') || normalizedPath.includes('\x00')) {
        throw new Error('invalid character in userPath');
    }

    if (normalizedPath.includes('..')) {
        const segments = normalizedPath.split('/');
        const stack = [];

        for (const segment of segments) {
            if (segment === '..') {
                stack.pop();
            } else if (segment !== '' && segment !== '.') {
                stack.push(segment);
            }
        }

        const result = baseDir + '/' + stack.join('/');
        return result;
    }

    throw new Error('userPath is outside base');
}
