export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('Both base and userPath must be strings');
  }

  if (base.startsWith('/') && !base.endsWith('/')) {
    throw new Error('Relative base path is not allowed');
  }

  const baseParts = base.split('/');
  const userParts = userPath.split('/');

  const result = [];
  for (const part of userParts) {
    if (part === '..') {
      if (result.length === 0 || result[result.length - 1] !== '..') {
        result.push('..');
      } else {
        result.pop();
      }
    } else if (part === '.') {
      continue;
    } else if (part === '') {
      continue;
    } else if (part === '%2e' || part === '%2f' || part === '%5c' || part.includes('\x00')) {
      throw new Error('Invalid character in userPath');
    } else {
      result.push(part);
    }
  }

  const joinedPath = baseParts.concat(result).join('/');

  if (!joinedPath.startsWith(base)) {
    throw new Error('Path would leave base');
  }

  return joinedPath;
}
